export const BODY: string = "\n<p>إنشاء GIF من صور عمل قصير: تجمع بضع صور وترفعها كإطارات وتضبط التوقيت وتنزّل الحركة. يمر هذا الدليل بكل خطوة بالترتيب، من اختيار الإطارات إلى مشاركة الملف المنتهي.</p>\n<p>قبل أن تبدأ تحتاج شيئًا واحدًا فقط: صورتين أو أكثر للتحريك. يمكن أن تكون صورًا أو لقطات شاشة أو صور منتج أو رسومًا. أحجام وأشكال متشابهة تعطي أنعم نتيجة، لكن الأداة تتعامل مع مجموعات مختلطة أيضًا.</p>\n<p>يقوم <a href=\"/ar/munshi-gif/\">منشئ GIF</a> بالعمل في متصفحك. لا شيء يُرفع إلى خادم ولا حساب، وGIF المنتهي يُنزّل مجانًا. اتبع الخطوات أدناه وستكون لديك حركة في دقائق معدودة.</p>\n<h2 id=\"step-1-gather-your-frames\">الخطوة 1: اجمع إطاراتك</h2>\n<p>اجمع الصور التي ستصبح إطارات GIF: GIF رد فعل يحتاج بضع صور تُظهر تغير تعبير. وعرض منتج يحتاج صورًا من زوايا مختلفة. وبرنامج تعليمي يحتاج لقطات لكل خطوة.</p>\n<p>خمسة إلى خمسة عشر إطارًا هو النطاق المناسب لمعظم GIF: إطارات أقل تعطي حركة قصيرة وحادة، بينما إطارات أكثر تعطي حركة أطول وأنعم. وأكثر من عشرين إطارًا غالبًا يجعل الملف كبيرًا جدًا للمشاركة. واستخدم صورًا بأبعاد متشابهة عندما تستطيع: إطارات بنفس الحجم والشكل تتحرك بسلاسة، بينما أحجام مختلفة جدًا تسبب قفزات وأشرطة سوداء. واقص أو غيّر حجم الصور الغريبة قبل الرفع.</p>\n<p>رتّب الإطارات في ذهنك قبل رفعها: دوران منتج يُقرأ باتجاه عقارب الساعة، وبرنامج تعليمي يُقرأ بترتيب الخطوات، ورد فعل يُقرأ كبناء وذروة.</p>\n<h2 id=\"step-2-upload-the-frames\">الخطوة 2: ارفع الإطارات</h2>\n<p>افتح <a href=\"/ar/munshi-gif/\">منشئ GIF</a> واسحب صور إطاراتك إلى منطقة الرفع، أو انقر لاختيارها من جهازك. ويمكنك رفع الكل دفعة واحدة، أو إضافة إطارات لاحقًا بزر إضافة إطارات.</p>\n<p>تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB لكل ملف: صور الهاتف واللقطات والرسوم تعمل. وصورة HEIC من iPhone تُرفع وتُحول تلقائيًا. وتظهر الإطارات بالترتيب الذي رفعتها به، كقائمة تستطيع إعادة ترتيبها: تحقق من أن كل الصور التي تحتاجها موجودة قبل المتابعة. وإطار مفقود أسهل إصلاحًا الآن من بعد التوليد.</p>\n<p>وإذا رفعت GIF موجودًا كإطار، تستطيع الأداة استخراج إطار واحد منه: هذا مفيد عندما تريد إعادة استخدام لحظة من حركة قديمة كجزء من حركة جديدة.</p>\n<h2 id=\"step-3-reorder-the-frames\">الخطوة 3: أعد ترتيب الإطارات</h2>\n<p>اسحب الإطارات إلى الترتيب الذي يروي القصة: الإطار الأول هو ما يراه الناس قبل أن تبدأ الحركة، والأخير هو ما يرونه قبل أن يعيد الحلقة، فكلاهما يهم.</p>\n<p>ضع أقوى إطار أولًا: في محادثة أو خلاصة، الإطار الأول هو المصغرة، ويقرر إن كان أحد سيشاهد الحركة. وإطار أول ممل يعني أن GIF يُتخطى. وراجع التسلسل بحثًا عن قفزات: إطار ينتمي لاحقًا في الحركة لكنه في بداية القائمة يخلق قفزة مرئية في الحركة. واقرأ قائمة الإطارات كقصة: يجب أن يتدفق كل إطار إلى التالي.</p>\n<p>احذف أي إطار لا يستحق مكانه: صورة ضبابية أو زاوية مكررة أو إطار لا يضيف شيئًا إلى القصة يجعل GIF أطول وأثقل فقط. إطارات أقل وأفضل تفوز دائمًا.</p>\n<h2 id=\"step-4-duplicate-or-remove-frames\">الخطوة 4: كرّر أو أزل إطارات</h2>\n<p>كرّر إطارًا عندما تريد إبقاءه أطول دون تغيير ضبط التوقيت: شريحة عنوان مكررة تُعرض ضعف الوقت، وإطار أخير مكرر يبقي النتيجة النهائية على الشاشة أطول قبل إعادة الحلقة.</p>\n<p>التكرار أيضًا طريقة لتكرار لحظة داخل الحركة: زاوية منتج معروضة مرتين تُقرأ كوقفة، وإطار رد فعل معروض مرتين يُقرأ كتأكيد. وأزل الإطارات التي تجعل GIF بطيئًا دون إضافة معنى: شبه مكرر للإطار السابق أو صورة ضبابية أو إطار يكرر السابق فقط يمكن أن يذهب. وكل إطار تزيله يوفر حجم ملف ووقت مشاهدة.</p>\n<p>لا تحتاج رفع نفس الملف مرتين لتكرار إطار: ضبط التكرار ينسخ الإطار داخل الأداة، فاللحظة المكررة لا تكلف رفعًا إضافيًا ولا إدارة ملفات.</p>\n<h2 id=\"step-5-set-frame-delays\">الخطوة 5: حدد تأخيرات الإطارات</h2>\n<p>تأخير الإطار هو كم يبقى كل إطار على الشاشة، ويقرر كيف تبدو الحركة: ابدأ بأحد الإعدادات السريعة: 1 أو 2 أو 5 أو 10 إطارات في الثانية. خمسة إطارات في الثانية إيقاع جيد لمعظم GIF.</p>\n<p>حدد تأخيرًا واحدًا لكل الإطارات أولًا، ثم اضبط الإطارات الفردية التي تحتاج وقتًا أكثر: شريحة عنوان تحتاج البقاء أطول لتُقرأ، وإطار حركة سريعة يحتاج وقتًا أقل. وتأخير موحد لكل إطار هو أكثر أخطاء توقيت GIF شيوعًا: الإطارات المهمة تمر مسرعة دون قراءة، بينما إطارات الحركة تتباطأ. وامنح الإطارات المهمة وقتًا أكثر وإطارات الانتقال وقتًا أقل.</p>\n<p>راقب معاينة التوقيت الحية وأنت تضبط: تأخير يبدو جيدًا كرقم قد يبدو سيئًا في الحركة، والمعاينة تُظهر الإحساس الحقيقي. وإذا مرت الحركة بسرعة، أبطئ التأخير الأساسي؛ وإذا تراخت، سرّعه.</p>\n<h2 id=\"step-6-set-the-loop-count\">الخطوة 6: حدد عدد التكرارات</h2>\n<p>اختر كم مرة يُشغل GIF: حلقة لا نهائية تُشغل إلى الأبد، ما يناسب ردود الفعل والزخارف وأي شيء يجب أن يجذب الانتباه مرارًا. إنه السلوك الافتراضي لمعظم GIF.</p>\n<p>حلقة محدودة تُشغل عددًا ثابتًا من المرات ثم تتوقف عند الإطار الأخير: يناسب برنامجًا تعليميًا أو عرضًا حيث يجب أن ينتهي الشخص عند الحالة النهائية. وتشغيل واحد يُظهر الحركة مرة واحدة ويتوقف: يناسب كشفًا، مثل قبل وبعد يجب أن ينتهي عند بعد. ويرى الشخص التغيير ثم النتيجة.</p>\n<p>طابق التكرار مع الوجهة: رد فعل محادثة يريد حلقة لا نهائية، وعرض منتج يريد بضع تكرارات، وخطوة برنامج تعليمي تريد أن تنتهي عند النتيجة. والتكرار الخاطئ يجعل GIF جيدًا يبدو غير مكتمل أو مزعجًا.</p>\n<h2 id=\"step-7-choose-frame-fit\">الخطوة 7: اختر ملاءمة الإطار</h2>\n<p>تقرر ملاءمة الإطار ما يحدث عندما تكون لإطاراتك نسب مختلفة: احتواء يلائم كل إطار داخل حجم الإخراج دون قص، فيبقى الإطار كله مرئيًا لكن قد تظهر أشرطة فارغة. وتغطية تملأ حجم الإخراج بالكامل بقص الإطار، فلا أشرطة فارغة لكن حواف بعض الإطارات قد تُقص. وتعطي حركة نظيفة ممتلئة على حساب بعض المحتوى.</p>\n<p>اختر احتواء عندما يهم كل جزء من كل إطار، مثل برنامج تعليمي حيث زر مقصوص سيخفي الخطوة. واختر تغطية عندما يجب أن تملأ الحركة الإطار بنظافة، مثل لافتة أو خلفية. وإذا شاركت كل إطاراتك نفس الأبعاد، فالملاءمة لا تهم، لأنه لا شيء لقصه أو ملئه: الملاءمة تهم فقط لمجموعات إطارات بأحجام مختلطة، فلا تقلق بشأنها للملفات المتسقة.</p>\n<h2 id=\"step-8-set-the-output-size\">الخطوة 8: حدد حجم الإخراج</h2>\n<p>حدد عرض الإخراج للمكان الذي سيُشارك فيه GIF: عرض نحو 480 بكسلًا يناسب المحادثة والخلاصات الاجتماعية، حيث يُرى GIF على هاتف. وعرض أكبر يناسب موقعًا أو عرضًا، حيث يُرى GIF على شاشة كبيرة.</p>\n<p>تبقى النسبة ثابتة عندما تعدّل عرض الإخراج، فتغيير العرض يقيّم GIF كله بدل تمديده: حدد العرض مرة واحدة ويتبع الارتفاع الإطارات. وأصغر غالبًا أفضل لـGIF: GIF بعرض 480 بكسلًا صغير بما يكفي للمشاركة بسرعة وكبير بما يكفي ليُرى بوضوح. وGIF بعرض 1000 بكسل له أربعة أضعاف البكسلات وملف أكبر بكثير.</p>\n<p>راجع حدود الوجهة قبل التوليد: بعض تطبيقات المحادثة والمنصات تقلل GIF الكبيرة أو ترفض ملفات تتجاوز حد حجم، فـGIF ضخم يهدر بيانات دون فائدة.</p>\n<h2 id=\"step-9-check-the-live-preview\">الخطوة 9: راجع المعاينة الحية</h2>\n<p>افتح معاينة التوقيت الحية وراقب الحركة تُشغل بضبطك الحالي: هذا هو الاختبار الصادق: تُظهر المعاينة التوقيت المنتهي والتكرار وحجم الإطار كما سيشاهده الناس.</p>\n<p>ابحث عن ثلاث مشاكل: إطار يمر بسرعة كبيرة وقفزة حيث ينكسر الترتيب وإعادة حلقة تبدو مفاجئة. والإطاران الأول والأخير يقرران مدى سلاسة الحلقة: إذا كانا متشابهين، تبدو إعادة التشغيل سلسة؛ وإذا كانا مختلفين جدًا، تبدو قفزة. وأصلح المشاكل في المعاينة بدل بعد التنزيل: اضبط تأخيرًا أو أعد ترتيب إطار أو غيّر عدد التكرارات، ثم راقب المعاينة مجددًا. وكل إصلاح يستغرق ثوانٍ في المعاينة لكنه يكلف توليدًا كاملًا بعد التنزيل.</p>\n<p>راجع المعاينة على هاتفك إذا كان GIF لمحادثة أو خلاصة: GIF يبدو سلسًا على شاشة سطح مكتب قد يبدو سريعًا على هاتف، والهاتف هو حيث الجمهور.</p>\n<h2 id=\"step-10-generate-and-download\">الخطوة 10: ولّد ونزّل</h2>\n<p>عندما تبدو المعاينة جيدة، ولّد GIF: ترمّز الأداة الإطارات إلى ملف GIF89a قياسي في متصفحك، ما يستغرق ثوانٍ لـGIF قصير ووقتًا أطول لـGIF طويل.</p>\n<p>انتبه إلى تحذير GIF الكبير: إذا تجاوز الملف المقدر 5 MB أو 15 MB، ستخبرك الأداة. وقلل عرض الإخراج أولًا، لأن تقليله إلى النصف يقطع البكسلات إلى الربع. ونزّل الملف المنتهي، الذي يُحفظ باسم animated_compressmypic.gif: غيّر اسمه إلى شيء ذي معنى قبل مشاركته، مثل product-demo.gif أو birthday-reaction.gif، لتجده لاحقًا.</p>\n<p>افتح GIF المنزّل وشغّله مرة لتأكيد أنه يعمل: راجع التوقيت والتكرار والحجم. وإذا كان شيء خطأ، غيّر الضبط في الأداة وولّد مجددًا.</p>\n<h2 id=\"fixing-a-gif-that-is-too-large\">كيف تصلح GIF كبيرًا جدًا</h2>\n<p>GIF كبير جدًا غالبًا له أحد أسباب ثلاثة: إطارات كثيرة جدًا أو أبعاد كبيرة جدًا أو سرعة عالية جدًا: أصلحها بترتيب التأثير، بدءًا بالأبعاد.</p>\n<p>قلل عرض الإخراج إلى النصف فيتقلص الملف بشكل كبير، لأن عدد البكسلات ينخفض إلى الربع: GIF بعرض 480 بكسلًا هو ربع حجم نفس GIF بعرض 960 بكسلًا. ثم قلّص عدد الإطارات: احذف الإطارات التي تكرر السابق أو تضيف قليلًا إلى القصة. وكل إطار محذوف توفير مباشر في حجم الملف، وGIF أقصر غالبًا أفضل على أي حال.</p>\n<p>وأخيرًا، اخفض سرعة الإطارات: النزول من عشرة إطارات في الثانية إلى خمسة يقلل إطارات الحركة في الثانية إلى النصف. وإذا ما زال GIF يحتاج أن يكون أصغر بعدها، فكر في <a href=\"/ar/daght-gif/\">ضاغط GIF</a> لضغط إضافي.</p>\n<h2 id=\"sharing-your-gif\">كيف تشارك GIF</h2>\n<p>شارك ملف GIF مباشرة في تطبيقات محادثة مثل WhatsApp وTelegram وSlack وDiscord، التي تشغل GIF مضمنًا: ارفع الملف كمرفق أو الصقه في الرسالة، فيتحرك لمن يشاهده.</p>\n<p>وعلى المنصات الاجتماعية، ارفع GIF كملف وسائط: معظم الخلاصات تقبل رفع GIF وتشغلها تلقائيًا، مع أن بعضها يحول GIF إلى فيديو خلف الكواليس. وفي موقع، ضمّن GIF بوسم صورة عادي: يُشغل تلقائيًا عندما تحمل الصفحة، فضعه حيث تضيف الحركة قيمة لا تشتيتًا. وGIF في كل قسم يصبح ضجيجًا؛ GIF واحد في المكان الصحيح يصبح لحظة.</p>\n<p>احتفظ بنسخة من صور الإطارات إضافة إلى GIF المنتهي: إذا احتجت لاحقًا حجمًا آخر أو تكرارًا آخر أو إطارًا مصححًا، تتيح لك الإطارات إعادة التوليد في دقائق.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق GIF</h2>\n<p>اجمع خمسة إلى خمسة عشر إطارًا بأبعاد متساوية وارفعها ورتبها بترتيب القصة وكرّر الإطارات التي تحتاج تأكيدًا. وحدد تأخيرًا أساسيًا قرب خمسة إطارات في الثانية.</p>\n<p>حدد عرض الإخراج للوجهة واختر احتواء أو تغطية لإطارات بأحجام مختلطة، وراجع معاينة التوقيت الحية قبل التوليد. وانتبه إلى تحذير GIF الكبير.</p>\n<p>للدليل الكامل، اقرأ <a href=\"/ar/blog/dalil-munshi-gif/\">الدليل الكامل لمنشئ GIF</a>، ولتوازن الحجم بالتفصيل اقرأ <a href=\"/ar/blog/muaddal-itarat-gif-wa-hajm-al-malaf/\">معدل إطارات GIF وحجم الملف: سلس مقابل صغير</a>. وأنشئ GIF من <a href=\"/ar/munshi-gif/\">منشئ GIF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم صورة أحتاج لإنشاء GIF؟","answer":"تحتاج صورتين على الأقل، لأن GIF سلسلة إطارات تُشغل بالتسلسل. وخمسة إلى خمسة عشر إطارًا هو النطاق المناسب لمعظم GIF: إطارات أقل تعطي حركة قصيرة وحادة، وأكثر تعطي حركة أطول وأنعم."},{"question":"هل يمكنني إضافة إطارات أكثر بعد أن أبدأ؟","answer":"نعم، يتيح لك ضبط إضافة إطارات إضافة صور أكثر في أي وقت، حتى بعد تحديد التوقيت. وتنضم الإطارات الجديدة إلى نهاية القائمة، ويمكنك سحبها إلى الموضع الصحيح."},{"question":"كيف أجعل إطارًا يبقى أطول على الشاشة؟","answer":"امنح ذلك الإطار تأخيرًا أطول، أو كرّره ليظهر مرتين متتاليتين. وكلا الطريقتين تعملان؛ تأخير أطول أنظف لشريحة عنوان، بينما التكرار أسرع لرد فعل."},{"question":"أي صيغ صور يمكنني استخدامها كإطارات GIF؟","answer":"تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB لكل ملف. والصور واللقطات والرسوم تعمل كإطارات. وإذا رفعت GIF موجودًا، تستطيع الأداة استخراج إطار واحد منه."},{"question":"لماذا ملف GIF كبير جدًا؟","answer":"يحفظ GIF كل إطار كصورة كاملة، فإطارات كثيرة وأبعاد كبيرة وسرعة عالية تجمع حجمًا. وقلل عرض الإخراج أولًا، لأن تقليله إلى النصف يقطع البكسلات إلى الربع، ثم أزل الإطارات الزائدة."},{"question":"هل يمكنني استخدام GIF الذي أنشأته في WhatsApp وإنستغرام؟","answer":"نعم، يشغل WhatsApp وTelegram وSlack وDiscord وإنستغرام GIF. وارفع الملف كمرفق وسائط فيتحرك مضمنًا. وبعض المنصات تحول GIF إلى فيديو خلف الكواليس، لكن الحركة تظهر مع ذلك."}];
